param(
  [string]$OutFile = "D:\lab\Kur_IB\.env.production.local",
  [switch]$Force
)

if ((Test-Path $OutFile) -and -not $Force) {
  Write-Output "File already exists: $OutFile"
  Write-Output "Run again with -Force if you want to replace it."
  exit 0
}

$bytes = New-Object byte[] 48
$rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
$rng.GetBytes($bytes)
$rng.Dispose()
$authSecret = [Convert]::ToBase64String($bytes).Replace("+", "-").Replace("/", "_")

$content = @"
# Generated by scripts/phase-e/init-production-env.ps1
# Fill DATABASE_URL and NEXTAUTH_URL with your real production values.
# Leave VERCEL_PROJECT_PRODUCTION_URL empty on Vercel unless you intentionally
# need a non-Vercel fallback host. When used, store host only without https://.

DATABASE_URL=
AUTH_SECRET="$authSecret"
NEXTAUTH_URL=
VERCEL_PROJECT_PRODUCTION_URL=

GOOGLE_CLIENT_ID=
GOOGLE_CLIENT_SECRET=
GITHUB_CLIENT_ID=
GITHUB_CLIENT_SECRET=

AI_PROVIDER=fallback
OPENAI_API_KEY=
GIGACHAT_CLIENT_ID=
GIGACHAT_CLIENT_SECRET=
"@

Set-Content -Path $OutFile -Value $content -Encoding utf8

Write-Output "Created $OutFile"
Write-Output "AUTH_SECRET has been generated automatically."
Write-Output "You still need to fill DATABASE_URL and NEXTAUTH_URL."
Write-Output "Leave VERCEL_PROJECT_PRODUCTION_URL empty on Vercel unless you need a custom fallback host."
